// isNextOnNewLine tests whether t2 is on a different line from t1
func isNextOnNewLine(t1, t2 Token) bool {
	// If the second token is from a different file,
	// we can assume it's from a different line
	if t1.File != t2.File {
		return true
	}

	// If the second token is from a different import chain,
	// we can assume it's from a different line
	if len(t1.imports) != len(t2.imports) {
		return true
	}
	for i, im := range t1.imports {
		if im != t2.imports[i] {
			return true
		}
	}

	// If the first token (incl line breaks) ends
	// on a line earlier than the next token,
	// then the second token is on a new line
	return t1.Line+t1.NumLineBreaks() < t2.Line
}

func (l *lexer) collectTokens(filename string, input []byte) ([]Token, error) {
	if err := l.load(bytes.NewReader(input)); err != nil {
		return nil, err
	}
	if l.line < 1 {
		l.line = 1
	}
	var tokens []Token
	for {
		found, err := l.next()
		if err != nil {
			return nil, err
		}
		if !found {
			break
		}
		l.token.File = filename
		if l.skippedLines < 0 {
			l.skippedLines = 0
		}
		tokens = append(tokens, l.token)
	}
	return tokens, nil
}

func (l *lexer) validHeredocMarker(marker string) bool {
	if marker == "" {
		return false
	}
	if strings.ContainsAny(marker, " \t\r\n") {
		return false
	}
	return heredocMarkerRegexp.MatchString(marker)
}

func (l *lexer) quotedTokenText(tok Token) string {
	if tok.wasQuoted > 0 && tok.wasQuoted != '<' {
		return string(tok.wasQuoted) + tok.Text + string(tok.wasQuoted)
	}
	return tok.Text
}

func (l *lexer) scalarTokenValue(tok Token) any {
	if tok.wasQuoted > 0 {
		return tok.Text
	}
	if num, err := strconv.Atoi(tok.Text); err == nil {
		return num
	}
	if num, err := strconv.ParseFloat(tok.Text, 64); err == nil {
		return num
	}
	if b, err := strconv.ParseBool(tok.Text); err == nil {
		return b
	}
	return tok.Text
}

func (l *lexer) tokenOnSameLine(curr, next Token) bool {
	return !isNextOnNewLine(curr, next)
}

